import { loadFromGitHub } from 'gowm';

// Load crypto module from wasm-modules-repository
const crypto = await loadFromGitHub('benoitpetit/wasm-modules-repository', {
  path: 'crypto-wasm',
  filename: 'main.wasm',
  name: 'crypto-wasm',
  branch: 'master'
});

// Configure module
crypto.call('setSilentMode', true);

// Hash operations with error handling
const hashResult = crypto.call('hashSHA256', 'Hello World');
if (hashResult.error) {
  console.error('Hash error:', hashResult.error);
} else {
  console.log('Hash:', hashResult.hash);
  console.log('Algorithm:', hashResult.algorithm);
}

// Generate AES key
const keyResult = crypto.call('generateAESKey', 32); // 256-bit
if (keyResult.error) {
  console.error('Key generation failed:', keyResult.error);
  return;
}

// Encrypt data
const encryptResult = crypto.call('encryptAES', 'Secret message', keyResult.key);
if (encryptResult.error) {
  console.error('Encryption failed:', encryptResult.error);
  return;
}

console.log('Encrypted:', encryptResult.encryptedData);

// Decrypt data
const decryptResult = crypto.call('decryptAES', encryptResult.encryptedData, keyResult.key);
if (decryptResult.error) {
  console.error('Decryption failed:', decryptResult.error);
} else {
  console.log('Decrypted:', decryptResult.decryptedData);
}

// Comprehensive crypto toolkit for secure operations
import { loadFromGitHub } from 'gowm';

class CryptoToolkit {
  constructor() {
    this.crypto = null;
    this.ready = false;
    this.loadModule();
  }

  async loadModule() {
    try {
      this.crypto = await loadFromGitHub('benoitpetit/wasm-modules-repository', {
        path: 'crypto-wasm',
        filename: 'main.wasm',
        name: 'crypto-wasm',
        branch: 'master'
      });

      // Configure for production use
      this.crypto.call('setSilentMode', true);

      // Get available functions
      const functions = this.crypto.call('getAvailableFunctions');
      console.log('Available crypto functions:', functions);

      this.ready = true;
    } catch (error) {
      console.error('Failed to load crypto module:', error);
    }
  }

  // Secure hash operations
  hashSHA256(data) {
    if (!this.ready) throw new Error('Crypto module not ready');

    const result = this.crypto.call('hashSHA256', data);
    if (result.error) {
      throw new Error(result.error);
    }
    return result;
  }

  hashSHA512(data) {
    if (!this.ready) throw new Error('Crypto module not ready');

    const result = this.crypto.call('hashSHA512', data);
    if (result.error) {
      throw new Error(result.error);
    }
    return result;
  }

  // AES encryption/decryption
  generateAESKey(keySize = 32) {
    if (!this.ready) throw new Error('Crypto module not ready');

    const result = this.crypto.call('generateAESKey', keySize);
    if (result.error) {
      throw new Error(result.error);
    }
    return result;
  }

  encryptAES(data, key) {
    if (!this.ready) throw new Error('Crypto module not ready');

    const result = this.crypto.call('encryptAES', data, key);
    if (result.error) {
      throw new Error(result.error);
    }
    return result;
  }

  decryptAES(encryptedData, key) {
    if (!this.ready) throw new Error('Crypto module not ready');

    const result = this.crypto.call('decryptAES', encryptedData, key);
    if (result.error) {
      throw new Error(result.error);
    }
    return result;
  }

  // RSA operations
  generateRSAKeyPair(keySize = 2048) {
    if (!this.ready) throw new Error('Crypto module not ready');

    const result = this.crypto.call('generateRSAKeyPair', keySize);
    if (result.error) {
      throw new Error(result.error);
    }
    return result;
  }

  // Utility functions
  generateUUID() {
    if (!this.ready) throw new Error('Crypto module not ready');

    const result = this.crypto.call('generateUUID');
    if (result.error) {
      throw new Error(result.error);
    }
    return result;
  }
}

// Usage example
const cryptoKit = new CryptoToolkit();

// Wait for module to load
setTimeout(async () => {
  if (cryptoKit.ready) {
    try {
      // Hash operations
      const hash256 = cryptoKit.hashSHA256('Hello World');
      console.log('SHA256:', hash256.hash);

      // AES encryption
      const aesKey = cryptoKit.generateAESKey(32);
      const encrypted = cryptoKit.encryptAES('Secret message', aesKey.key);
      const decrypted = cryptoKit.decryptAES(encrypted.encryptedData, aesKey.key);

      console.log('Encrypted:', encrypted.encryptedData);
      console.log('Decrypted:', decrypted.decryptedData);

      // Generate UUID
      const uuid = cryptoKit.generateUUID();
      console.log('UUID:', uuid.uuid);

    } catch (error) {
      console.error('Crypto operation failed:', error.message);
    }
  }
}, 1000);

// Helper function for consistent crypto error handling
function handleCryptoResult(result, successCallback, errorCallback) {
  if (result.error) {
    errorCallback(result.error);
  } else {
    successCallback(result);
  }
}

// Usage examples with different crypto operations
const operations = [
  () => crypto.call('hashSHA256', 'test data'),
  () => crypto.call('generateAESKey', 32),
  () => crypto.call('encryptAES', 'data', 'invalid-key'), // Will fail
  () => crypto.call('generateUUID')
];

operations.forEach((operation, index) => {
  const result = operation();
  handleCryptoResult(
    result,
    (data) => console.log(`Operation ${index + 1} success:`, data),
    (error) => console.error(`Operation ${index + 1} failed:`, error)
  );
});

